use pstfree::{ltp::{read_node_pc,read_tc,Value},ndb::Pst};
use std::collections::BTreeMap;
fn main(){let mut p=Pst::open(&std::env::args().nth(1).unwrap()).unwrap();let ns=p.nodes();let mut counts=BTreeMap::new();for n in ns.iter().filter(|n|matches!(n.nid_type(),14|15|16)){let tc=read_tc(&mut p,n.bid_data,n.bid_sub).unwrap();for r in tc.rows{if let Some(m)=ns.iter().find(|m|m.nid==r.id){let pc=read_node_pc(&mut p,m).unwrap();for id in [0x0037,0x0e07,0x0e17,0x6612]{if let Some(v)=r.props.get(&id){let label=match v{Value::Int(iv)=>format!("{:04x}:int={:x}:pc_equal={}",id,iv,pc.props.get(&id).is_some_and(|x|format!("{:?}",x)==format!("{:?}",v))),Value::Str(s)=>format!("{:04x}:first_control={}:first_two_units={:?}",id,s.chars().next().is_some_and(|c|c.is_control()),s.encode_utf16().take(2).filter(|u|*u<32).collect::<Vec<_>>()),_=>format!("{:04x}:other",id)};*counts.entry(label).or_insert(0)+=1;}}}}}println!("{:?}",counts);}
